{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello सलोनी जी आपको ईज़ल wooden stand की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "आपको easel wooden stand की requirement थी ना?"
    },
    {
      "i": 3,
      "speaker": "caller",
      "text": "हाँ हाँ।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आपको कितने piece चाहिए?"
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "एक।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "समझ गई हूँ।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "चलिए अब height के बारे में बताइए आपको कौन सी चाहिए पाँच feet छः inch या कुछ और?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "five feet."
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अब material में क्या पसंद करेंगे?"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "pine wood, teak wood या कुछ और?"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "I mean fine."
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है Pine wood select कर लिया।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 19,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
